#!/usr/bin/env python3
"""Tests for check_makefile.py: each planted inconsistency (target missing
from .PHONY, phantom .PHONY entry, header/`all:` drift, stale or missing
generated-file entry) must fail; a consistent Makefile must pass.

Run: python3 .github/scripts/test_check_makefile.py
"""

import sys
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import check_makefile as g  # noqa: E402

GOOD = """# header
#   `make all` = generate build
#                check:
GENERATED := out/gen.go \\
	out/gen2.go
GENERATED_EXTERNAL := ext/zz_gen.go
.PHONY: all generate build check
all: generate build check
generate:
\tgo generate
build: generate
\tjavac
check:
\ttrue
define helper
\techo "x: y"
endef
"""
TRACKED = {"out/gen.go", "out/gen2.go", "ext/zz_gen.go", "a.go"}
HEADS = {"out/gen.go": ["// Code generated by x; DO NOT EDIT."]}


def run(text=GOOD, tracked=TRACKED, heads=HEADS, ignored=()):
    return g.check(text, set(tracked), lambda p: p in ignored, lambda p: heads.get(p, []))


class Gate(unittest.TestCase):
    def test_good(self):
        self.assertEqual(run(), [])

    def test_missing_phony(self):
        errs = run(GOOD + "fast-run:\n\ttrue\n")
        self.assertTrue(any("missing target 'fast-run'" in e for e in errs), errs)

    def test_phantom_phony(self):
        errs = run(GOOD.replace(".PHONY: all", ".PHONY: all gone"))
        self.assertTrue(any("'gone'" in e for e in errs), errs)

    def test_header_drift(self):
        errs = run(GOOD.replace("all: generate build check", "all: generate build check test"
                                ).replace(".PHONY: all", ".PHONY: test all") + "test:\n\ttrue\n")
        self.assertTrue(any("header" in e for e in errs), errs)

    def test_stale_generated_entry(self):
        errs = run(tracked=TRACKED - {"out/gen2.go"})
        self.assertTrue(any("out/gen2.go" in e and "stale" in e for e in errs), errs)

    def test_ignored_generated_entry_ok(self):
        self.assertEqual(run(tracked=TRACKED - {"out/gen2.go"}, ignored={"out/gen2.go"}), [])

    def test_unlisted_generated_file(self):
        heads = dict(HEADS, **{"a.go": ["// Code generated by tool; DO NOT EDIT.", "package a"]})
        errs = run(heads=heads)
        self.assertTrue(any("'a.go'" in e for e in errs), errs)


if __name__ == "__main__":
    unittest.main(verbosity=1)
